def cycle_info(nexts):
    def nxt(i):
        return nexts[i] if 0 <= i < len(nexts) else -1
    slow, fast = 0, 0
    while True:
        slow = nxt(slow)
        fast = nxt(nxt(fast))
        if slow == -1 or fast == -1:
            return [-1, 0]
        if slow == fast:
            break
    length = 1
    probe = nxt(slow)
    while probe != slow:
        probe = nxt(probe)
        length += 1
    a, b = 0, slow
    while a != b:
        a = nxt(a)
        b = nxt(b)
    return [a, length]

