def count_digit_range(lo, hi, d):
    def upto(n):
        if n < 0:
            return 0
        total = 1 if d == 0 else 0
        base = 1
        while base <= n:
            high = n // (base * 10)
            cur = (n // base) % 10
            low = n % base
            if d == 0:
                if high > 0:
                    total += (high - 1) * base + (low + 1 if cur == 0 else base)
            else:
                total += high * base
                if cur > d:
                    total += base
                elif cur == d:
                    total += low + 1
            base *= 10
        return total
    return upto(hi) - upto(lo - 1) if hi >= lo else 0

