def lcs_lex_smallest(a, b):
    n = len(a)
    m = len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
    out = []
    i = 0
    j = 0
    while i < n and j < m and dp[i][j] > 0:
        for c in sorted(set(a[i:])):
            p = a.find(c, i)
            q = b.find(c, j)
            if p < 0 or q < 0:
                continue
            if 1 + dp[p + 1][q + 1] == dp[i][j]:
                out.append(c)
                i = p + 1
                j = q + 1
                break
    return ''.join(out)

