def min_merge_cost(stones):
    n = len(stones)
    if n <= 1:
        return 0
    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] + stones[i]
    dp = [[0] * n for _ in range(n)]
    for width in range(2, n + 1):
        for i in range(0, n - width + 1):
            j = i + width - 1
            total = pre[j + 1] - pre[i]
            best = -1
            for k in range(i, j):
                cur = dp[i][k] + dp[k + 1][j] + total
                if best < 0 or cur < best:
                    best = cur
            dp[i][j] = best
    return dp[0][n - 1]

