def min_cover_circular_len(s, t):
    if len(t) == 0:
        return 0
    n = len(s)
    if n == 0:
        return -1
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    have = {}
    formed = 0
    left = 0
    best = n + 1
    d = s + s
    for right in range(0, 2 * n):
        c = d[right]
        if c in need:
            have[c] = have.get(c, 0) + 1
            if have[c] == need[c]:
                formed += 1
        while formed == len(need) and left <= right:
            if right - left + 1 < best:
                best = right - left + 1
            e = d[left]
            if e in need:
                if have[e] == need[e]:
                    formed -= 1
                have[e] = have.get(e, 0) - 1
            left += 1
    if best > n:
        return -1
    return best

