def longest_k_palindrome(s, k):
    n = len(s)
    best = 0
    for center in range(0, 2 * n - 1):
        left = center // 2
        right = left + center % 2
        bad = 0
        while left >= 0 and right < n:
            if s[left] != s[right]:
                bad += 1
                if bad > k:
                    break
