def count_digit_sum_divisible(n, k):
    digits = [int(c) for c in str(n)]
    dp_tight = [0] * k
    dp_free = [0] * k
    dp_tight[0] = 1
    for pos in range(len(digits)):
        limit = digits[pos]
        nxt_tight = [0] * k
        nxt_free = [0] * k
        for r in range(k):
            cnt_tight = dp_tight[r]
            if cnt_tight:
                for d in range(limit + 1):
                    nr = (r + d) % k
                    if d == limit:
                        nxt_tight[nr] += cnt_tight
                    else:
                        nxt_free[nr] += cnt_tight
            cnt_free = dp_free[r]
            if cnt_free:
                for d in range(10):
                    nxt_free[(r + d) % k] += cnt_free
        dp_tight = nxt_tight
        dp_free = nxt_free
    return dp_tight[0] + dp_free[0]

