    if n == 0:
        return 0 if k == 0 else -1
    if k < 0 or k > n:
        return -1
    NEG = -10 ** 15
    dp0 = [[NEG] * (k + 1) for _ in range(n)]
    dp1 = [[NEG] * (k + 1) for _ in range(n)]
