                base = cur[a]
                if base == NEG:
                    continue
                for b in range(k + 1 - a):
                    best = dp0[c][b]
                    if dp1[c][b] > best:
                        best = dp1[c][b]
                    if best == NEG:
                        continue
                    if base + best > nxt[a + b]:
                        nxt[a + b] = base + best
            cur = nxt
        dp0[i] = cur
        cur = [NEG] * (k + 1)
        if k >= 1:
            cur[1] = weights[i]
        for c in children[i]:
            nxt = [NEG] * (k + 1)
            for a in range(k + 1):
                base = cur[a]
                if base == NEG:
                    continue
