                    v = dp0[c][b]
                    if v == NEG:
                        continue
                    if base + v > nxt[a + b]:
                        nxt[a + b] = base + v
            cur = nxt
        dp1[i] = cur
    ans = dp0[0][k]
    if dp1[0][k] > ans:
        ans = dp1[0][k]
    return -1 if ans <= NEG // 2 else ans

