def tsp_min_path(dist):
    n = len(dist)
    if n <= 1:
        return 0
    INF = 10 ** 15
    size = 1 << n
    dp = [[INF] * n for _ in range(size)]
    dp[1][0] = 0
    for mask in range(size):
        row = dp[mask]
        for i in range(n):
            cur = row[i]
            if cur == INF or not (mask >> i) & 1:
                continue
            di = dist[i]
            for j in range(n):
                if (mask >> j) & 1:
                    continue
                nm = mask | (1 << j)
                v = cur + di[j]
                if v < dp[nm][j]:
                    dp[nm][j] = v
    full = size - 1
    best = INF
    for i in range(n):
        if dp[full][i] < best:
            best = dp[full][i]
    return best

