def prefix_function(t):
    m = len(t)
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and t[i] != t[j]:
            j = pi[j - 1]
        if t[i] == t[j]:
            j += 1
        pi[i] = j
    return pi

def shortest_palindrome_append(s):
    n = len(s)
    if n == 0:
        return ""
    rev = s[::-1]
    t = rev + "#" + s
    pi = prefix_function(t)
    longest = pi[len(t) - 1]
    return s + rev[longest:]

