def knapsack_2d(weights, volumes, values, cap_w, cap_v):
    n = len(weights)
    dp = [[0] * (cap_v + 1) for _ in range(cap_w + 1)]
    for i in range(n):
        wi = weights[i]
        vi = volumes[i]
        val = values[i]
        if wi > cap_w or vi > cap_v:
            continue
        for cw in range(cap_w, wi - 1, -1):
            row = dp[cw - wi]
            cur = dp[cw]
            for cv in range(cap_v, vi - 1, -1):
                cand = row[cv - vi] + val
                if cand > cur[cv]:
                    cur[cv] = cand
    return dp[cap_w][cap_v]

