def min_concat_number(nums):
    strs = [str(x) for x in nums]
    n = len(strs)
    if n == 0:
        return ""
    for i in range(1, n):
        key = strs[i]
        j = i - 1
        while j >= 0 and key + strs[j] < strs[j] + key:
            strs[j + 1] = strs[j]
            j -= 1
        strs[j + 1] = key
    out = ""
    for item in strs:
        out = out + item
    allzero = True
    for c in out:
        if c != "0":
            allzero = False
            break
    if allzero:
        return "0"
    return out

