def min_rooms_with_gap(intervals, gap):
    if len(intervals) == 0:
        return 0
    order = sorted(range(len(intervals)), key=lambda i: (intervals[i][0], intervals[i][1]))
    heap = []
    for i in order:
        s = intervals[i][0]
        e = intervals[i][1]
        if len(heap) > 0 and heap[0] + gap <= s:
            heap[0] = e
            p = 0
            while True:
                l = 2 * p + 1
                r = l + 1
                m = p
                if l < len(heap) and heap[l] < heap[m]:
                    m = l
                if r < len(heap) and heap[r] < heap[m]:
                    m = r
                if m == p:
                    break
                tmp = heap[p]
                heap[p] = heap[m]
                heap[m] = tmp
                p = m
        else:
            heap.append(e)
            p = len(heap) - 1
            while p > 0:
                par = (p - 1) // 2
                if heap[par] <= heap[p]:
                    break
                tmp = heap[p]
                heap[p] = heap[par]
                heap[par] = tmp
                p = par
    return len(heap)

