def stone_game_diff(nums):
    n = len(nums)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            opts = [nums[i] - dp[i + 1][j], nums[j] - dp[i][j - 1]]
            if length == 2:
                opts.append(nums[i] + nums[j])
            elif length >= 3:
                opts.append(nums[i] + nums[i + 1] - dp[i + 2][j])
                opts.append(nums[j] + nums[j - 1] - dp[i][j - 2])
            best = opts[0]
            for v in opts:
                if v > best:
                    best = v
            dp[i][j] = best
    return dp[0][n - 1]

