def shortest_path_cost(n, edges, src, dst):
    if src == dst:
        return 0
    adj = [[] for _ in range(n)]
    for e in edges:
        adj[e[0]].append((e[1], e[2]))
    INF = 10 ** 18
    dist = [INF] * n
    dist[src] = 0
    while True:
        u = -1
        best = INF
        for i in range(n):
            if dist[i] < best:
                best = dist[i]
                u = i
        if u == -1:
            break
        if u == dst:
            return best
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return -1

def feasible_binary_array(n, constraints):
    V = n + 1
    edges = []
    for i in range(n):
        edges.append((i, i + 1, 0))
        edges.append((i + 1, i, -1))
    for c in constraints:
        l = c[0]
        r = c[1]
        lo = c[2]
        hi = c[3]
        edges.append((l, r + 1, lo))
        edges.append((r + 1, l, -hi))
    dist = [0] * V
    for _ in range(V):
        changed = False
        for u, v, w in edges:
            if dist[u] + w > dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            return True
    return False

